// Validate & prepare: turns the incoming payload into the exact body of CEKIVA's POST /v1/posts.
const SUPPORTED = ['linkedin', 'tiktok', 'youtube', 'pinterest', 'bluesky', 'discord', 'facebook_page', 'instagram', 'threads', 'facebook_reels'];
const ALIASES = { facebook: 'facebook_page', 'facebook-page': 'facebook_page', 'facebook page': 'facebook_page', reels: 'facebook_reels', 'facebook-reels': 'facebook_reels', 'facebook reels': 'facebook_reels', twitter: 'x' };
const RETIRED = { x: 'X (Twitter) is retired in CEKIVA and can no longer be posted to.' };
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const item = $input.first().json;
const baseUrl = String(item.cekiva_base_url || '').trim().replace(/\/+$/, '');
// The payload comes as the webhook body; any other trigger (Google Sheets, ...) may deliver the fields at the top level.
const p = item.body && typeof item.body === 'object' && !Array.isArray(item.body) ? item.body : item;

const list = (v) => (Array.isArray(v) ? v : typeof v === 'string' ? v.split(/[,\n;]+/) : v == null ? [] : [v]);
const bool = (v) => v === true || (typeof v === 'string' && v.trim().toLowerCase() === 'true');
const errors = [];

if (!/^https?:\/\//i.test(baseUrl)) errors.push('Setup: "cekiva_base_url" in the Config node must be an http(s) URL such as https://cekiva.com/api/v1.');

const text = p.text == null ? '' : String(p.text).trim();
const media = list(p.media_urls).map((u) => String(u).trim()).filter(Boolean);
const badMedia = media.filter((u) => !/^https?:\/\/\S+$/i.test(u));
if (badMedia.length) errors.push('"media_urls" must be public http(s) URLs; invalid: ' + badMedia.join(', '));
if (!text && media.length === 0) errors.push('"text" is required (it may only be empty when "media_urls" is given).');

const platforms = [...new Set(list(p.platforms).map((x) => String(x).trim().toLowerCase()).filter(Boolean).map((x) => ALIASES[x] || x))];
if (platforms.length === 0) errors.push('"platforms" is required: an array (or comma-separated string) with at least one of: ' + SUPPORTED.join(', ') + '.');
for (const x of platforms) {
  if (RETIRED[x]) errors.push(RETIRED[x]);
  else if (!SUPPORTED.includes(x)) errors.push('Unsupported platform "' + x + '". Supported: ' + SUPPORTED.join(', ') + '.');
}

let scheduledFor = null;
if (p.scheduled_at != null && String(p.scheduled_at).trim() !== '') {
  const ms = Date.parse(String(p.scheduled_at));
  if (Number.isNaN(ms)) errors.push('"scheduled_at" must be an ISO 8601 timestamp with a time zone, e.g. 2026-12-01T09:00:00Z.');
  else if (ms <= Date.now() + 30 * 1000) errors.push('"scheduled_at" must be in the future (at least 30 seconds ahead). Omit it to publish right away.');
  else scheduledFor = new Date(ms).toISOString();
}

const workspaceId = p.workspace_id == null ? '' : String(p.workspace_id).trim();
if (workspaceId && !UUID.test(workspaceId)) errors.push('"workspace_id" must be the UUID of a client workspace (listed by GET /v1/clients) — omit it to use your primary workspace.');

if (errors.length) {
  return [{ json: { ok: false, http_status: 422, body: { status: 'ERROR', http_status: 422, error: { kind: 'VALIDATION', code: 'INVALID_INPUT', stage: 'input', upstream_status: null, message: errors[0], hint: 'Fix the fields named in "details" and send the request again.', details: errors } } } }];
}

// The body of POST /v1/posts exactly as the CEKIVA backend expects it (SchedulePostRequest).
const request = { platforms, content: text, scheduled_for: scheduledFor || new Date().toISOString(), publish_now: !scheduledFor };
if (media.length === 1) request.image_url = media[0];
if (media.length > 1) { request.image_url = media[0]; request.media_urls = media; }
if (bool(p.require_approval)) request.require_approval = true; // wait for the client's approval link before publishing
if (bool(p.ai_generated)) request.ai_generated = true; // TikTok "AI-generated" label: only ever set by the poster, never automatically

return [{ json: { ok: true, base_url: baseUrl, lookup_workspace: workspaceId || null, request } }];

// Maps the caller's workspace_id to the client_id that CEKIVA's public API works with (GET /v1/clients lists every client workspace).
const prep = $('Validate & Prepare').first().json;
const r = $input.first().json; // full response of GET /v1/clients
if (r.error || r.statusCode !== 200) {
  return [{ json: { ok: false, stage: 'resolve_workspace', statusCode: r.statusCode, body: r.body, error: r.error } }];
}
const wanted = String(prep.lookup_workspace).toLowerCase();
const clients = (r.body && r.body.clients) || [];
const hit = clients.find((c) => [c.workspace_id, c.id, c.external_ref].some((v) => v && String(v).toLowerCase() === wanted));
if (!hit) {
  const known = clients.map((c) => (c.workspace_id || c.id) + ' (' + c.name + ')');
  return [{ json: { ok: false, stage: 'resolve_workspace', statusCode: 404, body: { error: { code: 'WORKSPACE_NOT_FOUND', message: 'workspace_id ' + prep.lookup_workspace + ' was not found among the workspaces of this API key.' + (known.length ? ' Available: ' + known.join('; ') + '.' : ' This key has no client workspaces yet — create one on the website first.'), hint: 'List the workspaces of this key with GET /v1/clients; client workspaces carry a workspace_id.' } } } }];
}
return [{ json: { ok: true, base_url: prep.base_url, request: { ...prep.request, client_id: hit.id }, workspace: { workspace_id: hit.workspace_id, client_id: hit.id, name: hit.name } } }];

// Turns CEKIVA's answer (or any failure on the way) into one uniform response.
const r = $input.first().json;
const stage = r.stage || 'dispatch';
const status = Number(r.statusCode) || 0;
// CEKIVA's structured error: { code: 'INSUFFICIENT_CREDITS', message: '...', hint: '...' } (English; the HTTP nodes send Accept-Language: en)
const up = r.body && typeof r.body === 'object' && !Array.isArray(r.body) && r.body.error && typeof r.body.error === 'object' ? r.body.error : null;
const detailOf = (b) => {
  if (b == null) return '';
  if (typeof b === 'string') return b.slice(0, 500);
  if (typeof b.detail === 'string') return b.detail;
  if (Array.isArray(b.detail)) return b.detail.map((d) => (d && d.msg) || JSON.stringify(d)).join('; ');
  return JSON.stringify(b).slice(0, 500);
};

if ((status === 200 || status === 201) && stage === 'dispatch' && Array.isArray(r.body)) {
  const posts = r.body.map((x) => ({ id: x.id, platform: x.platform, status: x.status, scheduled_for: x.scheduled_for, credits_charged: x.credits_charged }));
  let workspace = null;
  try { workspace = $('Pick client').first().json.workspace || null; } catch (e) { workspace = null; } // only when workspace_id was given
  return [{ json: { http_status: 200, body: { status: 'SUCCESS', post_ids: posts.map((x) => x.id), posts, total_credits_charged: posts.reduce((s, x) => s + (x.credits_charged || 0), 0), workspace } } }];
}

// kind = the coarse class (stable, UPPERCASE); code = CEKIVA's specific error code (UPPERCASE) when it sent one
const KINDS = { 401: 'AUTH', 402: 'INSUFFICIENT_CREDITS', 403: 'FORBIDDEN', 404: 'NOT_FOUND', 422: 'VALIDATION', 429: 'TRIAL_LIMIT' };
const HINTS = { // used only when CEKIVA sent no hint of its own
  AUTH: 'Check the "CEKIVA API key" credential (header Authorization: Bearer tplk_...).',
  INSUFFICIENT_CREDITS: 'Top up credits in CEKIVA (the workspace owner pays for their members).',
  FORBIDDEN: 'The Social Publisher module may be inactive, the account suspended or the client workspace archived.',
  NOT_FOUND: 'Check workspace_id and the other identifiers.',
  VALIDATION: 'CEKIVA rejected the content: see "message".',
  TRIAL_LIMIT: 'Free-trial daily limit reached: pick another day or platform.',
  SERVER_ERROR: 'CEKIVA answered with a server error. Nothing was published unless a post id came back.',
  NETWORK: 'CEKIVA could not be reached. Check "cekiva_base_url" in the Config node and the network path from n8n to CEKIVA.',
  CLIENT_ERROR: 'CEKIVA refused the request: see "message".',
};
let kind; let code; let message; let http;
if (!status) {
  kind = 'NETWORK'; code = 'CEKIVA_UNREACHABLE';
  message = String((r.error && (r.error.message || r.error.code)) || 'No response from CEKIVA.').slice(0, 300);
  http = 502;
} else if (status >= 500) {
  kind = 'SERVER_ERROR'; code = (up && up.code) || 'CEKIVA_SERVER_ERROR'; message = (up && up.message) || detailOf(r.body) || ('HTTP ' + status); http = 502;
} else {
  kind = KINDS[status] || 'CLIENT_ERROR'; code = (up && up.code) || ('HTTP_' + status); message = (up && up.message) || detailOf(r.body) || ('HTTP ' + status); http = status;
}
const hint = (up && up.hint) || HINTS[kind];
return [{ json: { http_status: http, body: { status: 'ERROR', http_status: http, error: { kind, code, stage, upstream_status: status || null, message, hint } } } }];
